{
  "scenario": "schelling",
  "phenomenon": "residential segregation dynamics",
  "indicators": [
    {
      "id": "mic_mean_local_similarity",
      "semantic_name": "Mean local same-group similarity",
      "scientific_definition": "Time series of the across-agent mean of each agent's same-group fraction among occupied Moore neighbours.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Local similarity is an individual-level primitive quantifying the immediate neighbourhood composition each agent experiences."
    },
    {
      "id": "mic_std_local_similarity",
      "semantic_name": "Standard deviation of local similarity",
      "scientific_definition": "Time series of the across-agent standard deviation of local same-group fractions.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Dispersion of individual local similarities captures how unevenly local neighbourhood experiences are distributed across agents."
    },
    {
      "id": "mic_q25_local_similarity",
      "semantic_name": "25th percentile of local similarity",
      "scientific_definition": "Time series of the 25th percentile of local same-group fractions across agents.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "quantile",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent",
        "q": 0.25
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Lower-tail local exposure indicates whether a meaningful subset of agents remains in low same-group local contexts."
    },
    {
      "id": "mic_q75_local_similarity",
      "semantic_name": "75th percentile of local similarity",
      "scientific_definition": "Time series of the 75th percentile of local same-group fractions across agents.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "quantile",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent",
        "q": 0.75
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Upper-tail local exposure tracks how concentrated high-similarity local contexts are among agents."
    },
    {
      "id": "mic_mean_neighbour_count",
      "semantic_name": "Mean occupied neighbour count",
      "scientific_definition": "Time series of the across-agent mean number of occupied Moore neighbours.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "local_process",
      "entities": "local neighbourhoods around agents",
      "source_fields": [
        "neighbour_count"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "field",
          "name": "neighbour_count"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Neighbour occupancy is a local primitive process reflecting how full the immediate surroundings of agents tend to be."
    },
    {
      "id": "mic_fraction_unhappy",
      "semantic_name": "Fraction of unhappy agents",
      "scientific_definition": "Time series of the fraction of agents whose local similarity is below the satisfaction tolerance.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "agents with an active dissatisfaction event",
      "source_fields": [
        "unhappy"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "unhappy"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "tolerance",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Higher tolerance raises the same-group threshold required for satisfaction, so more agents are classified as unhappy."
        }
      ],
      "scientific_rationale": "Unhappiness is the elementary dissatisfaction event driving relocation in the Schelling mechanism."
    },
    {
      "id": "mic_fraction_boundary_agent",
      "semantic_name": "Fraction of boundary agents",
      "scientific_definition": "Time series of the fraction of agents with at least one occupied different-group neighbour.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "intergroup local contact agents",
      "source_fields": [
        "boundary_agent"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "boundary_agent"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Boundary exposure is an interaction-level binary state indicating local contact between different groups."
    },
    {
      "id": "mic_fraction_moved",
      "semantic_name": "Fraction of agents that moved",
      "scientific_definition": "Time series of the fraction of agents that relocated during the recorded step.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "agents with a relocation event",
      "source_fields": [
        "moved"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "moved"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "move_probability",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Higher move_probability increases the chance that an unhappy agent attempts relocation, raising the moving fraction."
        }
      ],
      "scientific_rationale": "Actual relocation events are the direct behavioural output of dissatisfaction in the agent rules."
    },
    {
      "id": "mic_mean_move_distance_movers",
      "semantic_name": "Mean relocation distance among movers",
      "scientific_definition": "Time series of the average periodic Manhattan distance moved by agents that relocated during the step.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "relocating agents",
      "source_fields": [
        "moved",
        "move_distance"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "where",
          "condition": {
            "op": "field",
            "name": "moved"
          },
          "input": {
            "op": "field",
            "name": "move_distance"
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Relocation distance is an event-level measure of how far active movers travel under the current opportunity structure."
    },
    {
      "id": "mic_mean_destination_similarity_movers",
      "semantic_name": "Mean destination similarity among movers",
      "scientific_definition": "Time series of the average same-group neighbour fraction at selected destinations for agents that moved.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "relocating agents and their selected destinations",
      "source_fields": [
        "moved",
        "destination_similarity"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "where",
          "condition": {
            "op": "field",
            "name": "moved"
          },
          "input": {
            "op": "field",
            "name": "destination_similarity"
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "destination_preference",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Stronger destination_preference makes movers select the most similar sampled vacancy, increasing destination similarity among movers."
        }
      ],
      "scientific_rationale": "Destination similarity captures the local composition that movers actually select, reflecting destination preference."
    },
    {
      "id": "mic_corr_sim_neighbour_count",
      "semantic_name": "Correlation between local similarity and neighbour count",
      "scientific_definition": "Time series of the across-agent Pearson correlation between local same-group similarity and occupied neighbour count.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity",
        "neighbour_count"
      ],
      "computation": {
        "op": "correlation",
        "left": {
          "op": "field",
          "name": "local_similarity"
        },
        "right": {
          "op": "field",
          "name": "neighbour_count"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "This interaction-level association relates local occupancy density to local group composition across individual contexts."
    },
    {
      "id": "mic_variance_local_similarity",
      "semantic_name": "Variance of local similarity",
      "scientific_definition": "Time series of the across-agent variance of local same-group fractions.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "variance",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Variance provides a squared measure of individual-level dispersion of local similarity experiences."
    },
    {
      "id": "mic_unhappy_event_count",
      "semantic_name": "Count of individual unhappy events",
      "scientific_definition": "Time series of the number of individual agents whose local similarity is below the satisfaction tolerance.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "agents with an active dissatisfaction event",
      "source_fields": [
        "unhappy"
      ],
      "computation": {
        "op": "count",
        "input": {
          "op": "field",
          "name": "unhappy"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "tolerance",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Higher tolerance raises the same-group threshold required for satisfaction, increasing the number of dissatisfied agents."
        }
      ],
      "scientific_rationale": "This indicator explicitly uses the individual elementary dissatisfaction primitive unhappy rather than the aggregate unhappy_count log."
    },
    {
      "id": "mic_std_destination_similarity_movers",
      "semantic_name": "Standard deviation of destination similarity among movers",
      "scientific_definition": "Time series of the standard deviation of destination same-group similarity for agents that moved.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "relocating agents and selected destinations",
      "source_fields": [
        "moved",
        "destination_similarity"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "where",
          "condition": {
            "op": "field",
            "name": "moved"
          },
          "input": {
            "op": "field",
            "name": "destination_similarity"
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Dispersion of selected destination similarities indicates how uniformly movers obtain high-similarity destinations."
    },
    {
      "id": "mic_mean_sim_boundary",
      "semantic_name": "Mean local similarity among boundary agents",
      "scientific_definition": "Time series of the average local same-group similarity for agents with at least one different-group neighbour.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "boundary agents",
      "source_fields": [
        "boundary_agent",
        "local_similarity"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "where",
          "condition": {
            "op": "field",
            "name": "boundary_agent"
          },
          "input": {
            "op": "field",
            "name": "local_similarity"
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Boundary agents are directly exposed to intergroup contact, so their local similarity summarizes interaction-zone conditions."
    },
    {
      "id": "mic_entropy_local_similarity",
      "semantic_name": "Binned entropy of local similarity",
      "scientific_definition": "Time series of binned Shannon entropy of agent local same-group similarity across the agent population.",
      "phenomenon": "residential segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "binned_entropy",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent",
        "bins": 10
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Entropy of binned local similarity captures the diversity of individual local composition values in the population."
    },
    {
      "id": "meso_district_mean_local_similarity",
      "semantic_name": "Mean district local similarity",
      "scientific_definition": "Time series of the mean across fixed spatial districts of district-mean local same-group similarity.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "local_similarity",
        "district_id"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "local_similarity"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "mean"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Using district grouping preserves local-domain organization and averages district-level local similarity rather than collapsing to individual-level aggregation."
    },
    {
      "id": "meso_district_dispersion_local_similarity",
      "semantic_name": "Between-district dispersion of local similarity",
      "scientific_definition": "Time series of the standard deviation across districts of district-mean local similarity.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "local_similarity",
        "district_id"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "local_similarity"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "mean"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Between-district variation in mean local similarity measures whether district-level residential contexts diverge."
    },
    {
      "id": "meso_district_composition_entropy",
      "semantic_name": "Mean district group-composition entropy",
      "scientific_definition": "Time series averaging Shannon entropy of agent group labels within each fixed spatial district across districts.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "agent_group",
        "district_id"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "agent_group"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "entropy"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "District-level group entropy captures how mixed or homogeneous each local domain is in its group composition."
    },
    {
      "id": "meso_district_group1_fraction_dispersion",
      "semantic_name": "Between-district dispersion of group-1 fraction",
      "scientific_definition": "Time series of the standard deviation across districts of the fraction of agents belonging to group 1.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "agent_group",
        "district_id"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "agent_group"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "fraction"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Variation in group-1 fraction across districts reveals how unevenly groups occupy different local domains."
    },
    {
      "id": "meso_district_unhappy_fraction_std",
      "semantic_name": "Between-district standard deviation of unhappy fraction",
      "scientific_definition": "Time series of the standard deviation across fixed spatial districts of the fraction of unhappy agents in each district.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "unhappy",
        "district_id"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "unhappy"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "fraction"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "District-level variation in dissatisfaction prevalence localizes where behavioural pressure is concentrated rather than averaging it away."
    },
    {
      "id": "meso_district_boundary_fraction_std",
      "semantic_name": "Between-district standard deviation of boundary-agent fraction",
      "scientific_definition": "Time series of the standard deviation across fixed spatial districts of the fraction of agents with intergroup contact in each district.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "boundary_agent",
        "district_id"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "boundary_agent"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "fraction"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Between-district dispersion of boundary exposure identifies whether intergroup contact is evenly spread or concentrated in particular districts."
    },
    {
      "id": "meso_district_move_fraction_std",
      "semantic_name": "Between-district standard deviation of relocation fraction",
      "scientific_definition": "Time series of the standard deviation across fixed spatial districts of the fraction of agents that moved in each district.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "moved",
        "district_id"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "moved"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "fraction"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "District-level variation in relocation activity shows whether behavioural churn is localized in specific local domains."
    },
    {
      "id": "meso_district_neighbour_count_std",
      "semantic_name": "Between-district standard deviation of mean occupied neighbour count",
      "scientific_definition": "Time series of the standard deviation across fixed spatial districts of district-mean occupied neighbour count.",
      "phenomenon": "residential segregation dynamics",
      "scale": "meso",
      "entity_scope": "district",
      "entities": "fixed spatial districts",
      "source_fields": [
        "neighbour_count",
        "district_id"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "group_reduce",
          "values": {
            "op": "field",
            "name": "neighbour_count"
          },
          "groups": {
            "op": "field",
            "name": "district_id"
          },
          "axis": "agent",
          "reducer": "mean"
        },
        "axis": "group"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Between-district variation in occupance density reveals whether local neighbourhood fullness differs systematically across public spatial districts."
    },
    {
      "id": "macro_spatial_neighbor_similarity",
      "semantic_name": "Whole-grid spatial neighbor similarity",
      "scientific_definition": "Time series of the whole-system average same-group similarity between occupied grid neighbours.",
      "phenomenon": "residential segregation dynamics",
      "scale": "macro",
      "entity_scope": "whole_system",
      "entities": "entire periodic grid",
      "source_fields": [
        "state_grid"
      ],
      "computation": {
        "op": "spatial_neighbor_similarity",
        "input": {
          "op": "field",
          "name": "state_grid"
        }
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "This global structural operator summarizes same-group adjacency across the entire grid as a whole-system collective state."
    },
    {
      "id": "macro_connected_component_count",
      "semantic_name": "Connected component count",
      "scientific_definition": "Time series of the number of connected components in the occupancy grid.",
      "phenomenon": "residential segregation dynamics",
      "scale": "macro",
      "entity_scope": "whole_system",
      "entities": "entire periodic grid",
      "source_fields": [
        "state_grid"
      ],
